style.css:
/* INSTAGRAM LIQUID GLASS — STYLISH */
:root {
  color-scheme: dark !important;
  --glass-bg: rgba(22, 24, 38, 0.68);
  --glass-border: rgba(210, 195, 255, 0.18);
  --glass-accent: #c5a4ff;
}

html, body {
  background:
    radial-gradient(ellipse at 15% 0%, rgba(130, 85, 220, 0.15), transparent 45%),
    radial-gradient(ellipse at 90% 15%, rgba(70, 140, 220, 0.10), transparent 40%),
    #090b12 !important;
  color: #f4f0ff !important;
}

/* Translucent glass panels */
[role="dialog"],
[role="menu"],
[role="listbox"] {
  background: var(--glass-bg) !important;
  -webkit-backdrop-filter: blur(24px) saturate(160%) !important;
  backdrop-filter: blur(24px) saturate(160%) !important;
  border: 1px solid var(--glass-border) !important;
  border-radius: 20px !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3) !important;
}

/* Main Instagram background */
main,
[role="main"] {
  background-color: transparent !important;
}

/* Navigation and subtle borders */
nav,
header,
[role="navigation"] {
  border-color: var(--glass-border) !important;
}

/* Inputs and search bars */
input,
textarea,
[contenteditable="true"] {
  background: rgba(255, 255, 255, 0.055) !important;
  color: #f4f0ff !important;
  border: 1px solid var(--glass-border) !important;
  border-radius: 14px !important;
}

input::placeholder,
textarea::placeholder {
  color: #aaa6bd !important;
}

/* Buttons */
button,
[role="button"] {
  transition: background 0.2s ease !important;
}

button:hover,
[role="button"]:hover {
  background-color: rgba(197, 164, 255, 0.12) !important;
}

/* Lavender links */
a:hover {
  color: #d7c2ff !important;
}

/* Slim custom scrollbar */
* {
  scrollbar-color: rgba(197, 164, 255, 0.4) transparent !important;
  scrollbar-width: thin !important;
}

*::-webkit-scrollbar {
  width: 7px !important;
}

*::-webkit-scrollbar-thumb {
  background: rgba(197, 164, 255, 0.4) !important;
  border-radius: 20px !important;
}
